package com.djibtout.backend.entity;
import jakarta.persistence.*;import org.hibernate.annotations.CreationTimestamp;import java.time.LocalDateTime;
@Entity @Table(name="seller_fulfillments",uniqueConstraints=@UniqueConstraint(columnNames={"order_id","seller_id"})) public class SellerFulfillment{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(optional=false)@JoinColumn(name="order_id")private Order order;@ManyToOne(optional=false)@JoinColumn(name="seller_id")private User seller;@Enumerated(EnumType.STRING)private OrderStatus status=OrderStatus.PROCESSING;@Column(length=100)private String trackingNumber;@CreationTimestamp private LocalDateTime createdAt;public Long getId(){return id;}public Order getOrder(){return order;}public void setOrder(Order v){order=v;}public User getSeller(){return seller;}public void setSeller(User v){seller=v;}public OrderStatus getStatus(){return status;}public void setStatus(OrderStatus v){status=v;}public String getTrackingNumber(){return trackingNumber;}public void setTrackingNumber(String v){trackingNumber=v;}public LocalDateTime getCreatedAt(){return createdAt;}}
